import type { CacheItem } from "./types.js";

/**
 * A section of the note.
 * Sections are root level Markdown blocks, which can be used to divide the document up.
 * ```markdown
 * # Heading section
 *
 * Paragraph section
 *
 * > [!NOTE]
 * > Callout section
 * ```
 * @public
 */
export interface SectionCache extends CacheItem {
	/**
	 * The block ID of this section, if defined.
	 * @public
	 */
	id?: string | undefined;

	/**
	 * The type string generated by the parser.
	 * Typing is non-exhaustive, more types can be available than are documented here.
	 * @public
	 */
	type:
		| "blockquote"
		| "callout"
		| "code"
		| "element"
		| "footnoteDefinition"
		| "heading"
		| "html"
		| "list"
		| "paragraph"
		| "table"
		| "text"
		| "thematicBreak"
		| "yaml"
		| string;
}
